  const [fotosPorNome, setFotosPorNome] = useState<Record<string, string>>({});
  const [escalasPorData, setEscalasPorData] = useState<Record<string, any>>({});
  const [listasMusicasAbertas, setListasMusicasAbertas] = useState<Record<string, boolean>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const repertoriosQuery = query(
      collection(firestore, 'repertorios'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(repertoriosQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(docSnap => ({
        id: docSnap.id,
        ...docSnap.data(),
      }));
      setRepertorios(data);
      setLoading(false);
    }, (error) => {
      console.log('Erro ao buscar repertórios:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(firestore, 'presencas'), snapshot => {
      const fotosUsuarios = snapshot.docs.reduce((acc, docSnap) => ({
        ...acc,
        ...(docSnap.data().fotosUsuarios || {}),
      }), {} as Record<string, string>);

      const fotos: Record<string, string> = { ...fotosUsuarios };
      Object.values(UID_TO_NOME).forEach(nome => {
        const foto = obterFotoPorNome(fotosUsuarios, nome);
        if (foto) fotos[nome] = foto;
      });
      setFotosPorNome(fotos);
    });

    return unsubscribe;
  }, []);

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(firestore, 'escalas'), snapshot => {
      const escalas = snapshot.docs.reduce((acc, docSnap) => {
        const dados = docSnap.data();
        const dataId = normalizarDataId(typeof dados.data === 'string' ? dados.data : docSnap.id);
        acc[dataId] = dados;
        return acc;
      }, {} as Record<string, any>);

      setEscalasPorData(escalas);
    }, error => {
      console.log('Erro ao buscar escalas para repertórios:', error);
    });

    return unsubscribe;
  }, []);

